<script setup>
import {computed,ref} from 'vue';
import {state,go} from '../store';
import Icon from './Icon.vue';
const selected=ref(0),token=ref(''),sample=ref('');
const id=computed(()=>state.language==='id');
const level=computed(()=>state.levels[selected.value]||state.levels[0]);
const faqs=computed(()=>id.value?[
 ['Untuk siapa INBAF?','Mahasiswa internasional, pekerja, peneliti, dan siapa pun yang mempelajari Bahasa Indonesia sebagai bahasa asing.'],
 ['Keterampilan apa yang diuji?','Paket dapat menggabungkan menyimak, tata bahasa, membaca, kosakata, menulis, berbicara, dan komunikasi kontekstual. Lihat susunan sesi sebelum memulai.'],
 ['Kapan hasil saya tersedia?','Soal objektif dinilai otomatis. Jika Anda mengirim esai atau rekaman, hasil akhir menunggu penilaian Superadmin menggunakan rubrik.'],
 ['Apakah level A1–C2 merupakan kesetaraan resmi?','Level adalah klasifikasi internal INBAF. Pemetaan ke CEFR perlu divalidasi secara empiris dan tidak menyatakan kesetaraan resmi dengan TOEFL, UKBI, atau sertifikasi lain.'],
 ['Apa yang terjadi jika koneksi terputus?','Jawaban yang belum terkirim disimpan sementara pada perangkat dan dicoba kembali saat koneksi pulih. Waktu tetap berjalan di server. Gunakan koneksi stabil dan perhatikan indikator penyimpanan.'],
 ['Bagaimana memeriksa sertifikat?','Pindai QR pada PDF atau masukkan token verifikasi. Halaman publik menunjukkan validitas, masa berlaku, dan status pencabutan.']
]:[
 ['Who is INBAF for?','International students, professionals, researchers, and anyone learning Indonesian as a foreign language.'],
 ['Which skills does an assessment cover?','Packages can combine listening, grammar, reading, vocabulary, writing, speaking, and contextual communication. Review the sections before you start.'],
 ['When will I receive my result?','Objective responses are scored automatically. If you submit writing or a recording, your final result waits for an administrator to assess it using the rubric.'],
 ['Are A1–C2 levels officially equivalent to CEFR?','Levels are internal INBAF classifications. CEFR mapping requires empirical validation and does not establish official equivalence to TOEFL, UKBI, or other certifications.'],
 ['What happens if my connection drops?','Unsynced responses are buffered on your device and retried when the connection returns. The server timer continues. Use a stable connection and watch the save indicator.'],
 ['How do I verify a certificate?','Scan the PDF QR code or enter its verification token. The public record shows validity, expiry, and revocation status.']
]);
</script>
<template>
<div class="landing-details">
<section class="detail-section competencies-story"><div><div class="eyebrow">{{id?'BAHASA DALAM KEHIDUPAN':'LANGUAGE IN REAL LIFE'}}</div><h2>{{id?'Lebih dari satu keterampilan.':'More than a single skill.'}}</h2><p>{{id?'Dari memahami pengumuman hingga menyampaikan gagasan, pilih ujian dengan kompetensi yang sesuai tujuan Anda.':'From understanding an announcement to expressing an idea, choose an assessment with the competencies that fit your goals.'}}</p><button class="button" @click="go(state.user?'/tests':'/register')">{{id?'Jelajahi paket ujian':'Explore assessments'}}<Icon name="ArrowUpRight" :size="17"/></button></div><div class="competency-map"><div class="map-center"><img src="/brand/favicon.svg" alt=""><strong>INBAF</strong></div><div v-for="c in state.competencies" :key="c.id" class="map-skill"><span :style="{background:c.color+'15',color:c.color}"><Icon :name="c.icon" :size="20"/></span><div><strong>{{id?c.name:c.name_en}}</strong><p>{{c.description}}</p></div></div></div></section>
<section class="detail-section level-story"><div class="section-intro"><div class="eyebrow">{{id?'PAHAMI POSISI ANDA':'UNDERSTAND WHERE YOU ARE'}}</div><h2>{{id?'Langkah demi langkah.':'One level at a time.'}}</h2><p>{{id?'Jelajahi klasifikasi kemahiran internal INBAF. Ambang dan kompetensi ditentukan oleh lembaga penyelenggara.':'Explore INBAF’s internal proficiency classifications. Thresholds and competencies are configured by your assessment institution.'}}</p></div><div class="level-tabs" role="tablist" aria-label="Proficiency levels"><button v-for="(l,i) in state.levels" :key="l.id" role="tab" :aria-selected="selected===i" :class="{selected:selected===i}" @click="selected=i"><span>{{l.code}}</span><small>{{l.name}}</small></button></div><div v-if="level" class="level-detail" role="tabpanel"><span class="level-code">{{level.code}}</span><div><h3>{{level.name}}</h3><p>{{level.description}}</p></div><span class="level-threshold">{{id?'Ambang internal':'Internal threshold'}}<strong>{{level.min_score}} / 100</strong></span></div></section>
<section class="detail-section sample-story"><div class="sample-card"><span class="badge blue">{{id?'CONTOH INTERAKSI · TIDAK DINILAI':'INTERACTIVE SAMPLE · UNSCORED'}}</span><span class="sample-category">GRAMMAR / TATA BAHASA</span><h3>Saya tinggal ___ Jakarta.</h3><div class="sample-options"><button v-for="(option,i) in ['di','ke','dari']" :key="option" :class="{selected:sample===option}" @click="sample=option"><span>{{String.fromCharCode(65+i)}}</span>{{option}}<Icon v-if="sample===option" name="CircleCheck" :size="18"/></button></div><p v-if="sample" class="sample-feedback" aria-live="polite">{{sample==='di'?(id?'Tepat. Kata depan “di” menunjukkan tempat tinggal.':'Correct. The preposition “di” indicates where someone lives.'):(id?'Coba lagi. Pilih kata depan yang menunjukkan lokasi.':'Try again. Choose the preposition that indicates a location.')}}</p><p v-else class="sample-feedback">{{id?'Pilih jawaban untuk mencoba interaksi soal.':'Choose a response to try a question interaction.'}}</p></div><div><div class="eyebrow">{{id?'KENALI PENGALAMAN UJIAN':'GET TO KNOW THE EXPERIENCE'}}</div><h2>{{id?'Fokus pada jawaban Anda.':'Make room for your best answer.'}}</h2><p>{{id?'Setiap sesi memiliki petunjuk, navigasi soal, penanda tinjauan, dan penyimpanan otomatis. Writing memberi ruang untuk gagasan Anda; speaking menyimpan rekaman untuk ditinjau penilai.':'Each session includes instructions, question navigation, review flags, and automatic saving. Writing gives your ideas space; speaking records your response for an assessor to review.'}}</p><div class="experience-list"><span><Icon name="Clock3" :size="19"/>{{id?'Waktu divalidasi server':'Time validated by the server'}}</span><span><Icon name="CloudCheck" :size="19"/>{{id?'Status penyimpanan terlihat':'Visible answer save status'}}</span><span><Icon name="Radar" :size="19"/>{{id?'Analisis per kompetensi':'Results by competency'}}</span></div></div></section>
<section class="detail-section public-verify"><div><span class="metric-icon cyan"><Icon name="ShieldCheck" :size="25"/></span><h2>{{id?'Pencapaian yang dapat diperiksa.':'An achievement you can verify.'}}</h2><p>{{id?'Sertifikat yang memenuhi syarat memiliki nomor unik, QR, dan catatan verifikasi publik. Periksa status langsung dari data penerbit.':'Eligible certificates include a unique number, QR code, and public verification record. Check their status directly against the issuer’s records.'}}</p></div><form @submit.prevent="go('/verify/'+encodeURIComponent(token.trim()))"><label for="public-verification-token">{{id?'Token verifikasi sertifikat':'Certificate verification token'}}</label><input id="public-verification-token" v-model="token" required maxlength="128" :placeholder="id?'Salin token dari tautan QR':'Paste the token from the QR link'"><button class="button" type="submit">{{id?'Periksa sertifikat':'Verify certificate'}}<Icon name="ArrowRight" :size="17"/></button><span>{{id?'Informasi pribadi ditampilkan secara terbatas.':'Public records display limited personal information.'}}</span></form></section>
<section class="detail-section faq-story"><div class="section-intro"><div class="eyebrow">{{id?'SEBELUM ANDA MULAI':'BEFORE YOU BEGIN'}}</div><h2>{{id?'Pertanyaan yang sering diajukan.':'A few things you might be wondering.'}}</h2></div><div class="faq-list"><details v-for="[question,answer] in faqs" :key="question"><summary>{{question}}<Icon name="Plus" :size="19"/></summary><p>{{answer}}</p></details></div></section>
</div>
